                "iteration": None,
                "complete_objective": float(
                    completion.objective
                ),
                "status": "PASS",
            }
        )
    except (IndexError, KeyError, TypeError, ValueError) as exc:
        failures.append(str(exc))
        complete_candidate_evaluation_trace.append(
            {
